<?php
namespace App\Http\Controllers\Staff;
use App\Enums\Permission; use App\Models\Question; use App\Models\Subject; use App\Services\QuestionBank\QuestionPresenter; use App\Services\QuestionBank\QuestionService; use Illuminate\Http\Request; use Inertia\Inertia;
class QuestionBankController { public function index(Request $r,QuestionPresenter $p){$u=$r->user();$ids=$u->taughtSubjectIds();$q=Question::with(QuestionPresenter::STAFF_RELATIONS)->whereIn('subject_id',$ids)->when($r->string('search')->toString(),fn($x,$v)=>$x->where('prompt','like','%'.$v.'%'))->when($r->integer('subject_id'),fn($x,$v)=>$x->where('subject_id',$v))->latest()->paginate(20)->withQueryString();return Inertia::render('staff/question-bank/index',['questions'=>$q->through(fn($x)=>$p->staff($x)),'subjects'=>Subject::whereIn('id',$ids)->orderBy('name')->get(['id','code','name'])]);} public function create(Request $r){return Inertia::render('staff/question-bank/create',['subjects'=>Subject::whereIn('id',$r->user()->taughtSubjectIds())->get(['id','code','name'])]);} public function store(Request $r,QuestionService $s){$d=$r->validate(['subject_id'=>'required|integer','question_topic_id'=>'nullable|integer','type'=>'required|in:multiple_choice,true_false,essay','prompt'=>'required|string|max:10000','points'=>'required|numeric|min:0.01|max:100','explanation'=>'nullable|string','choices'=>'array','choices.*.text'=>'required|string|max:1000','choices.*.is_correct'=>'boolean']);$s->create($r->user(),$d);return redirect('/question-bank')->with('success','Question created.');} public function edit(Question $question,Request $r,QuestionPresenter $p){abort_unless($r->user()->teachesSubject($question->subject_id),403);return Inertia::render('staff/question-bank/edit',['question'=>$p->staff($question),'subjects'=>Subject::whereIn('id',$r->user()->taughtSubjectIds())->get(['id','code','name'])]);} public function update(Request $r,Question $question,QuestionService $s){$d=$r->validate(['question_topic_id'=>'nullable|integer','type'=>'sometimes|in:multiple_choice,true_false,essay','prompt'=>'sometimes|string|max:10000','points'=>'sometimes|numeric|min:0.01|max:100','explanation'=>'nullable|string','choices'=>'array','choices.*.text'=>'required|string|max:1000','choices.*.is_correct'=>'boolean']);$s->update($r->user(),$question,$d);return back()->with('success','Question updated.');} public function toggle(Request $r,Question $question){abort_unless($r->user()->teachesSubject($question->subject_id),403);$question->update(['is_active'=>!$question->is_active,'updated_by'=>$r->user()->id]);return back();} }
